// What the setup coach is told about an existing project before it reads
// anything: its history and the documentation already in it. While planning
// the coach has only tools that read files, so it cannot ask git itself; and
// a project's own pages are where its knowledge already is, to link to
// rather than write again.
import { spawnSync } from "node:child_process";
import { readdirSync, readFileSync } from "node:fs";
import { join, relative } from "node:path";
import { GIT } from "@software-factory/knowledge-base";
// Folders that hold what was installed or made, never the project's own pages.
const MADE = new Set([
    "node_modules",
    "dist",
    "build",
    "coverage",
    "vendor",
    "target",
    "out",
]);
const MAX_COMMITS = 25;
const MAX_PAGES = 60;
const MAX_DEPTH = 4;
export function projectFacts(folder) {
    return `${history(folder)}\n\n${documentation(folder)}`;
}
// How long the project has been worked on, how lately, by how many people,
// and what the latest work was.
function history(folder) {
    const run = spawnSync(GIT, ["log", "--date=short", "--format=%ad%x09%ae%x09%s"], { cwd: folder, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
    const commits = run.status === 0
        ? run.stdout
            .split("\n")
            .filter(Boolean)
            .map((line) => {
            const [date = "", who = "", subject = ""] = line.split("\t");
            return { date, who, subject };
        })
        : [];
    const first = commits.at(-1);
    const last = commits[0];
    if (!first || !last)
        return "Its history: none (no git, or no commits yet).";
    const people = new Set(commits.map((commit) => commit.who)).size;
    const latest = commits
        .slice(0, MAX_COMMITS)
        .map((commit) => `- ${commit.date} ${commit.subject.slice(0, 140)}`);
    return [
        `Its history: ${String(commits.length)} commits from ${first.date} to ${last.date}, by ${String(people)} ${people === 1 ? "person" : "people"}. The latest:`,
        ...latest,
    ].join("\n");
}
// The Markdown pages in the project, shallowest first, each with its title.
function documentation(folder) {
    const pages = markdownIn(folder, 0).sort((a, b) => depth(a) - depth(b) || a.localeCompare(b));
    if (pages.length === 0)
        return "Its own documentation: none.";
    const listed = pages
        .slice(0, MAX_PAGES)
        .map((path) => `- ${relative(folder, path)}${titleOf(path)}`);
    const more = pages.length > MAX_PAGES
        ? [`- and ${String(pages.length - MAX_PAGES)} more`]
        : [];
    return [
        "Its own documentation (read it first; link to it, never write it again):",
        ...listed,
        ...more,
    ].join("\n");
}
function markdownIn(folder, level) {
    let entries;
    try {
        entries = readdirSync(folder, { withFileTypes: true });
    }
    catch {
        return [];
    }
    return entries.flatMap((entry) => {
        if (entry.name.startsWith(".") || MADE.has(entry.name))
            return [];
        const path = join(folder, entry.name);
        if (entry.isDirectory())
            return level < MAX_DEPTH ? markdownIn(path, level + 1) : [];
        return /\.mdx?$/i.test(entry.name) ? [path] : [];
    });
}
function depth(path) {
    return path.split(/[\\/]/).length;
}
// ": <the first heading>", or nothing when the page has none.
function titleOf(path) {
    try {
        const heading = readFileSync(path, "utf8")
            .split("\n")
            .find((line) => line.startsWith("# "));
        const title = heading?.slice(2).trim();
        return title ? `: ${title.slice(0, 80)}` : "";
    }
    catch {
        return "";
    }
}
